import{_ as t,o as i,c as s,a2 as a}from"./chunks/framework.CWWEQfK7.js";const u=JSON.parse('{"title":"Add an API endpoint: complete the boundary, permission, and test work","description":"Add an endpoint through the existing Ershu API layers, choose the right identity dependency and error meaning, and test every security boundary.","frontmatter":{"page_id":"development-add-api","title":"Add an API endpoint: complete the boundary, permission, and test work","description":"Add an endpoint through the existing Ershu API layers, choose the right identity dependency and error meaning, and test every security boundary."},"headers":[],"relativePath":"en/development/add-api.md","filePath":"en/development/add-api.md","lastUpdated":1786289447000}'),r={name:"en/development/add-api.md"};function o(n,e,d,l,c,h){return i(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="add-an-api-endpoint-complete-the-boundary-permission-and-test-work" tabindex="-1">Add an API endpoint: complete the boundary, permission, and test work <a class="header-anchor" href="#add-an-api-endpoint-complete-the-boundary-permission-and-test-work" aria-label="Permalink to &quot;Add an API endpoint: complete the boundary, permission, and test work&quot;">​</a></h1><p>An endpoint is more than a path and response. It decides who can call it, which module owns the data, how failure is represented, and whether Cookies, MCP keys, and project permissions stay inside their intended boundaries.</p><h2 id="first-confirm-that-the-feature-belongs-to-api" tabindex="-1">First confirm that the feature belongs to API <a class="header-anchor" href="#first-confirm-that-the-feature-belongs-to-api" aria-label="Permalink to &quot;First confirm that the feature belongs to API&quot;">​</a></h2><p>API owns HTTP, browser login, Cookies, CSRF, status-code mapping, chat, streaming, and web administration. Do not put these changes directly into API:</p><table tabindex="0"><thead><tr><th>Change</th><th>Start in</th></tr></thead><tbody><tr><td>Shared data model, migration, permission rule, or query</td><td>Core</td></tr><tr><td>Analysis execution, indexing, LSP, or model orchestration</td><td>Worker</td></tr><tr><td>MCP tool or output format</td><td>MCP</td></tr><tr><td>Page, interaction, or browser state</td><td>Frontend</td></tr></tbody></table><p>API may depend only on a pinned Core version, never on Worker or MCP. If a new endpoint needs a shared field, first add the Core model and migration and complete Core tests. Then update API&#39;s pinned Core commit to the version containing that change.</p><h2 id="follow-the-existing-four-layers" tabindex="-1">Follow the existing four layers <a class="header-anchor" href="#follow-the-existing-four-layers" aria-label="Permalink to &quot;Follow the existing four layers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Directory</th><th>Responsibility</th></tr></thead><tbody><tr><td>Request and response models</td><td><code>api/src/ershu/api/schemas/</code></td><td>Fields, types, lengths, and basic format</td></tr><tr><td>Business services</td><td><code>api/src/ershu/api/services/</code></td><td>Post-identity business rules, database operations, and audit</td></tr><tr><td>HTTP routes</td><td><code>api/src/ershu/api/routes/</code></td><td>Path, method, dependencies, and response model</td></tr><tr><td>Root router</td><td><code>api/src/ershu/api/router.py</code></td><td>Registers each subrouter in the unified API</td></tr></tbody></table><p><code>api_main.py</code> mounts the root router under <code>/api/v1</code>. A subrouter should declare only its own relative prefix rather than repeating the version path.</p><p>The current system-settings endpoint is a concrete end-to-end reference:</p><ul><li>models: <code>schemas/system_settings.py</code>;</li><li>business logic: <code>services/system_settings.py</code>;</li><li>routes: <code>routes/system_settings.py</code>;</li><li>registration: <code>system_settings.router</code> in <code>router.py</code>;</li><li>final paths: <code>GET</code> and <code>PATCH /api/v1/admin/system-settings</code>, plus <code>DELETE /api/v1/admin/system-settings/{name}</code>.</li></ul><p>It also shows administrator identity, a database session, input validation, audit, commit, and response reread working together. Follow the separation for the new behavior; do not copy the whole file blindly.</p><h2 id="choose-the-correct-identity-dependency" tabindex="-1">Choose the correct identity dependency <a class="header-anchor" href="#choose-the-correct-identity-dependency" aria-label="Permalink to &quot;Choose the correct identity dependency&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dependency</th><th>Accepted identity</th><th>Use it for</th></tr></thead><tbody><tr><td><code>current_user</code></td><td>Browser session or user Bearer token; rejects MCP keys</td><td>Normal web-user endpoints</td></tr><tr><td><code>current_auth_context</code></td><td>User token or MCP key</td><td>Read endpoints that intentionally support MCP and continue to enforce project and key scope</td></tr><tr><td><code>admin_user</code></td><td>Administrator user</td><td>User, global setting, credential, and other administration endpoints</td></tr><tr><td><code>reject_mcp_key_auth</code></td><td>Explicitly rejects an MCP key after building an auth context</td><td>Audit logs, key management, and other actions that require a real user</td></tr></tbody></table><p>Authentication is not resource authorization. Project routes must still call Core project-membership and permission services. MCP-capable routes must restrict both project and capability to the key&#39;s scope.</p><p>An endpoint without an identity dependency needs a clear reason. Health is a public liveness signal. A repository webhook instead uses its own timestamp, nonce, and HMAC signature. <code>/api/v1/webhooks/</code> is excluded from browser CSRF middleware, so the webhook route&#39;s signature validation is mandatory.</p><h2 id="validate-input-in-the-right-layer" tabindex="-1">Validate input in the right layer <a class="header-anchor" href="#validate-input-in-the-right-layer" aria-label="Permalink to &quot;Validate input in the right layer&quot;">​</a></h2><ul><li>Put field type, requiredness, length, and structure in Pydantic models. Request parsing failures of this kind normally return 422.</li><li>Put conflicts, permissions, and state rules that require database reads in the service layer.</li><li>Call existing Core services for shared rules instead of writing an approximate copy in a route.</li><li>Preserve original bytes when verification depends on the exact request body, as webhook signatures do.</li></ul><p><code>get_session()</code> provides a database session but does not automatically commit business changes. Follow the matching service pattern and handle writes, audit, commit, and failure cleanup explicitly. Tests should prove that a failed operation leaves no partial result.</p><h2 id="use-the-common-error-meanings" tabindex="-1">Use the common error meanings <a class="header-anchor" href="#use-the-common-error-meanings" aria-label="Permalink to &quot;Use the common error meanings&quot;">​</a></h2><p>API maps Core <code>ErshuError</code> kinds to a consistent JSON error response:</p><table tabindex="0"><thead><tr><th>Error kind</th><th style="text-align:right;">HTTP status</th></tr></thead><tbody><tr><td><code>invalid_input</code></td><td style="text-align:right;">400</td></tr><tr><td><code>unauthenticated</code></td><td style="text-align:right;">401</td></tr><tr><td><code>permission_denied</code></td><td style="text-align:right;">403</td></tr><tr><td><code>not_found</code></td><td style="text-align:right;">404</td></tr><tr><td><code>conflict</code></td><td style="text-align:right;">409</td></tr><tr><td><code>gone</code></td><td style="text-align:right;">410</td></tr><tr><td><code>rate_limited</code></td><td style="text-align:right;">429</td></tr><tr><td><code>internal</code></td><td style="text-align:right;">500</td></tr><tr><td><code>upstream_failure</code></td><td style="text-align:right;">502</td></tr><tr><td><code>unavailable</code></td><td style="text-align:right;">503</td></tr></tbody></table><p>Do not return 500 for user input, and do not handcraft a different error body in every route merely to choose a status. Add a stable machine-readable code only when clients need a branch, as the tested <code>csrf_invalid</code> response does.</p><h2 id="register-the-route-and-check-path-conflicts" tabindex="-1">Register the route and check path conflicts <a class="header-anchor" href="#register-the-route-and-check-path-conflicts" aria-label="Permalink to &quot;Register the route and check path conflicts&quot;">​</a></h2><ol><li>Give the subrouter an appropriate <code>APIRouter</code> prefix.</li><li>Import and register it exactly once in <code>api/src/ershu/api/router.py</code>.</li><li>Check whether a static path can be consumed first by a dynamic path such as <code>/{id}</code>.</li><li>Assign a tag consistent with the existing API navigation.</li><li>In development, inspect <code>/docs</code> and confirm the method, final <code>/api/v1</code> path, request model, and response model.</li></ol><p><code>/docs</code> exists only under <code>ENVIRONMENT=development</code>. Seeing a route there does not prove that its permission and transaction behavior is correct; tests remain authoritative.</p><h2 id="test-four-result-classes" tabindex="-1">Test four result classes <a class="header-anchor" href="#test-four-result-classes" aria-label="Permalink to &quot;Test four result classes&quot;">​</a></h2><p>API repository policy requires every new or changed route to cover at least:</p><ol><li><strong>Success</strong>: status, response model, database change, and audit result are correct.</li><li><strong>No permission</strong>: unauthenticated callers, regular users, wrong project members, or insufficient MCP scope are rejected correctly.</li><li><strong>Invalid input</strong>: wrong types, boundary values, state conflicts, and missing resources return stable statuses.</li><li><strong>Security</strong>: CSRF on Cookie writes, webhook signatures, credential exposure, or another endpoint-specific boundary.</li></ol><p>Tests normally use FastAPI <code>TestClient</code> with a temporary SQLite database for route behavior. Add a real PostgreSQL integration check for PostgreSQL-specific migrations or constraints; SQLite alone cannot prove them.</p><p>Also check that:</p><ul><li>responses do not expose tokens, ciphertext, private keys, or internal exception details;</li><li>repeated submissions have a clear idempotent or conflict result;</li><li>a failed write leaves the session usable and no partial commit behind;</li><li>API tests do not import <code>ershu.workers</code>, <code>ershu.mcp</code>, or test helpers from another repository.</li></ul><h2 id="run-repository-checks" tabindex="-1">Run repository checks <a class="header-anchor" href="#run-repository-checks" aria-label="Permalink to &quot;Run repository checks&quot;">​</a></h2><p>Use these commands in the API repository:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --extra</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --extra</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ruff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --extra</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ruff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> format</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --wheel</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Developers must run and record these checks; this page does not claim that they have passed. API currently pins Core to a private source, so a public environment without access cannot complete a fresh dependency installation. Treat that as a distribution prerequisite rather than inventing a public address.</p><h2 id="completion-criteria" tabindex="-1">Completion criteria <a class="header-anchor" href="#completion-criteria" aria-label="Permalink to &quot;Completion criteria&quot;">​</a></h2><ul><li>The route owns only the HTTP boundary, business rules live in services, and shared rules live in Core.</li><li>The final path is registered once under the intended <code>/api/v1</code> location.</li><li>Identity and resource authorization are explicit; an MCP key cannot accidentally gain user or administrator capabilities.</li><li>Pydantic parsing failures and business errors have stable, distinct meanings.</li><li>Success, no-permission, invalid-input, and security paths all have tests.</li><li>Commit, audit, and failure cleanup for writes have verifiable results.</li><li>Actual execution records, rather than documentation assumptions, show the full API tests, lint, format check, and build results.</li></ul><h2 id="source-locations" tabindex="-1">Source locations <a class="header-anchor" href="#source-locations" aria-label="Permalink to &quot;Source locations&quot;">​</a></h2><ul><li><code>api/src/ershu/api/router.py</code> and <code>api/src/ershu/api_main.py</code>: route registration and the <code>/api/v1</code> prefix.</li><li><code>api/src/ershu/api/deps.py</code>: user, administrator, and MCP identity dependencies.</li><li><code>api/src/ershu/api/database.py</code>: request database session.</li><li><code>api/src/ershu/api/error_handlers.py</code>: common error-status mapping.</li><li><code>api/src/ershu/api/schemas/system_settings.py</code>: existing request and response model example.</li><li><code>api/src/ershu/api/services/system_settings.py</code>: existing business, audit, commit, and reread example.</li><li><code>api/src/ershu/api/routes/system_settings.py</code>: existing administrator route example.</li><li><code>api/src/ershu/api/services/repositories/triggers.py</code>: webhook security outside Cookie authentication.</li><li><code>api/AGENTS.md</code>: module boundaries and route test requirements.</li><li><code>api/pyproject.toml</code>: test and build entry points and the pinned Core source.</li></ul>`,40)])])}const m=t(r,[["render",o]]);export{u as __pageData,m as default};
